/* setCommCode */
INSERT INTO TM_CODEXM (
            COMM_CODE
          , CODE_NAME
          , CODE_EXPL
          , USEE_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{commCode}
          , #{codeName}
          , #{codeExpl,jdbcType=VARCHAR}
          , #{useeYsno}
          , #{regiAdmn}
          , CURRENT_TIMESTAMP
          , #{updtAdmn}
          , CURRENT_TIMESTAMP
)

mapper.update:
