mapper.select:

SELECT /* getCodeName */
       COMD_NAME
  FROM TB_CODEXD
 WHERE COMM_CODE = #{commCode}
   AND COMD_CODE = #{comdCode}
   AND COALESCE(USEE_YSNO, #{yes}) = #{yes}


SELECT /* getCodeNameByComdCode */
       C.COMD_NAME
  FROM (  SELECT D.COMD_NAME
           FROM TB_CODEXD D
          WHERE D.COMD_CODE = #{comdCode}
            AND COALESCE(D.USEE_YSNO, #{yes}) = #{yes}
       ORDER BY D.COMM_CODE
       ) C
 LIMIT 1
